'use strict';
// Knowledge domains are editorial crosslinks: a book may belong to several.
let atlasDomains=[];
let launchDomain='flight';
const atlasGroups=[
 {id:'foundations',name:'Learn the language of reality.',caption:'01 / FOUNDATIONS',note:'Numbers, matter, living systems, and the habit of checking what you think you know.'},
 {id:'machines',name:'Make something move.',caption:'02 / MACHINES & ENVIRONMENTS',note:'Turn the foundations into vehicles, mechanisms, and systems that work beyond easy reach.'},
 {id:'civilization',name:'Ask what the power is for.',caption:'03 / INTELLIGENCE & CIVILIZATION',note:'More capability creates more choices. Read the technical ambition beside its human consequences.'}
];
function domainById(id){return atlasDomains.find(d=>d.id===id);}
function expandRoutes(){
 const extras=[['math','The language of the physical world'],['physics','Conservation, cosmos, and possibility'],['chemistry','From atoms to airframes'],['biology','Life inside the machine'],['ai','Computing meets the physical world'],['industry','Build it. Inspect it. Build it again.'],['defense','Power, strategy, and responsibility'],['healthspan','A longer life, an evidence-first question'],['philosophy','What is worth building?'],['institutions','How progress becomes durable'],['learning','The habits beneath the ambition'],['ocean','Engineering below the surface']];
 for(const [id,name] of extras){if(paths.some(p=>p.id==='field-'+id))continue;const d=domainById(id);if(!d)continue;const ordered=[...d.starters.map(x=>index.get(x)).filter(Boolean),...domainBooks(d).filter(b=>!d.starters.includes(b.id)).sort((a,b)=>a.difficulty-b.difficulty)];const unique=ordered.filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).slice(0,6);paths.push({id:'field-'+id,name,caption:d.tagline,desc:d.intro+' '+d.boundary,titles:unique.map(b=>b.title),project:d.practice});}
}
function domainBooks(d){return d?d.bookIds.map(id=>index.get(id)).filter(Boolean):[];}
function domainStar(d,i){const x=70+(i%4)*145,y=55+Math.floor(i/4)*91;return `<a href="#domain/${d.id}" aria-label="Explore ${esc(d.name)}"><circle cx="${x}" cy="${y}" r="23" class="star-halo"/><circle cx="${x}" cy="${y}" r="4" class="star-core"/><text x="${x}" y="${y+35}" text-anchor="middle">${esc(d.short)}</text></a>`;}
function constellation(){return `<svg viewBox="0 0 590 414" role="group" aria-labelledby="constellation-title"><title id="constellation-title">Connected fields: from mathematics and life to flight, space, robotics, and civilization. Each point opens a subject.</title><defs><radialGradient id="atlas-glow"><stop stop-color="#7eb9ad" stop-opacity=".16"/><stop offset="1" stop-color="#7eb9ad" stop-opacity="0"/></radialGradient></defs><circle cx="295" cy="207" r="205" fill="url(#atlas-glow)"/><g class="constellation-lines"><path d="M70 55 215 55 360 55 505 55 360 146 215 146 70 146 215 237 360 237 505 237 360 328 215 328 70 328M70 55 70 146 70 237 70 328M215 55 360 146 505 146 505 237 505 328M360 55 215 146 215 237 215 328M505 55 360 237 360 328 505 328M70 237 360 146M215 55 505 237"/></g>${atlasDomains.map(domainStar).join('')}</svg>`;}
function domainCard(d,i){return `<a class="domain-card" href="#domain/${d.id}" style="--domain-color:${d.color}"><div class="domain-card-top"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${domainBooks(d).length} BOOKS</span><span aria-hidden="true">↗</span></div><div class="domain-glyph" aria-hidden="true">${glyph(i)}</div><h3>${esc(d.name)}</h3><p>${esc(d.tagline)}</p><span class="domain-bottom">${esc(d.question)}</span></a>`;}
function atlasTeaser(){return `<section class="atlas-teaser"><div><span class="eyebrow">THE EXPANDED ATLAS / ${books.length} BOOKS · ${atlasDomains.length} CONNECTED FIELDS</span><h2>Your curiosity<br>has more than<br><em>one destination.</em></h2><p>Math to machines. Biology to habitats. Philosophy to the decisions that shape a civilization. Follow the connections—and find a small place to begin.</p><a href="#atlas" class="btn">Open the knowledge map <span>↗</span></a></div><div class="teaser-map">${constellation()}</div></section>`;}
function atlasPage(){return `<section class="atlas-hero"><div><span class="eyebrow">A LIBRARY FOR A LIFE OF BUILDING</span><h1>Learn the world.<br><em>Build what’s next.</em></h1><p>${books.length} books. ${atlasDomains.length} connected fields. A whole aerospace journey—and the ideas, living systems, and imagined worlds that make it bigger.</p><div class="atlas-stats"><div><strong>${books.filter(b=>b.kind==='nonfiction').length}</strong><span>WAYS TO UNDERSTAND</span></div><div><strong>${books.filter(b=>b.kind==='fiction').length}</strong><span>WORLDS TO IMAGINE</span></div></div><a class="text-link" href="#library">Search every book ↗</a></div><div class="atlas-constellation">${constellation()}<span>FOLLOW A POINT. FIND A CONNECTION.</span></div></section><section class="section launch-shelf"><div class="section-head"><div><span class="eyebrow">YOU DON’T NEED A 500-BOOK TO-DO LIST</span><h2>Start with three.</h2></div><label class="launch-select">What is pulling you in?<select id="launch-domain">${atlasDomains.map(d=>`<option value="${d.id}" ${launchDomain===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div><p class="launch-note">Three perspectives on the subject. Sample what interests you; check each book’s reading stage before choosing.</p><div id="launch-books">${launchShelf()}</div></section>${atlasGroups.map(g=>`<section class="section domain-group"><div class="section-head"><div><span class="eyebrow">${g.caption}</span><h2>${g.name}</h2></div><p>${g.note}</p></div><div class="domain-grid">${atlasDomains.map((d,i)=>({d,i})).filter(x=>x.d.group===g.id).map(({d,i})=>domainCard(d,i)).join('')}</div></section>`).join('')}<section class="section atlas-perspective"><span class="eyebrow">THE ENGINEERING DEGREE IS A SPINE, NOT A FENCE</span><h2>Specialize deeply.<br><em>Stay intellectually wide.</em></h2><div><p>Aerospace gives you a way into mechanics, fluids, structures, propulsion, dynamics, and design. Robotics adds sensing and control. Biology changes how you think about habitats. Philosophy asks what responsibilities come with building powerful systems.</p><p>This map connects those worlds; it is not an accredited curriculum. Use your actual course plan for prerequisites, a project for testing understanding, and this library for the questions that keep you moving.</p><a href="#journey" class="text-link">Connect a class to a capability →</a></div></section>`;}
function launchShelf(){const d=domainById(launchDomain)||atlasDomains[0];const bs=d.starters.map(id=>index.get(id)).filter(Boolean);return `<div class="launch-books">${bs.slice(0,3).map((b,i)=>`<article><span class="eyebrow">${['01 / A DOORWAY','02 / ANOTHER ANGLE','03 / A NEW QUESTION'][i]}</span><button data-open="${b.id}"><h3>${esc(b.title)}</h3><span>${esc(b.author)}</span></button><p>${esc(b.why)}</p><div><span class="badge">${esc(b.stage)}</span><button class="text-link" data-open="${b.id}">Explore ↗</button></div></article>`).join('')}</div><a class="text-link section-end" href="#domain/${d.id}">Explore ${esc(d.name.toLowerCase())} →</a>`;}
function domainPage(id){const d=domainById(id);if(!d)return notFound();const list=domainBooks(d);const featured=d.starters.map(id=>index.get(id)).filter(Boolean);const next=d.neighbors.map(domainById).filter(Boolean);return `<section class="page-head domain-head" style="--domain-color:${d.color}"><a href="#atlas" class="text-link">← The knowledge map</a><div class="domain-heading"><div><span class="eyebrow">${list.length} BOOKS / AN ENGINEERING CONNECTION</span><h1>${esc(d.name)}</h1><p class="lead">${esc(d.intro)}</p></div><div class="domain-head-art" aria-hidden="true">${glyph(atlasDomains.indexOf(d))}</div></div></section><section class="section domain-brief"><article><span class="eyebrow">WHY IT BELONGS IN THIS JOURNEY</span><h2>${esc(d.tagline)}</h2><p>${esc(d.connection)}</p></article><article><span class="eyebrow">BRING IT BACK TO EARTH</span><h2>A question you can work on.</h2><p>${esc(d.practice)}</p><p class="note">${esc(d.boundary)}</p><a class="text-link" href="#journal">Keep a field note →</a></article></section><section class="section" style="padding-top:20px"><div class="section-head"><div><span class="eyebrow">A SMALL FIRST SHELF</span><h2>Three ways in.</h2></div><a href="#library/${d.id}" class="btn small light">Browse all ${list.length} books ↗</a></div>${cards(featured)}</section><section class="section domain-neighbors"><div class="section-head"><div><span class="eyebrow">FOLLOW THE CONNECTIONS</span><h2>One subject opens another.</h2></div></div><div class="domain-grid">${next.map(x=>domainCard(x,atlasDomains.indexOf(x))).join('')}</div></section>`;}
function exportLearningLog(){const notes=journeyState.entries;const lines=['# Learning field notes','', 'Exported from Ditch the Scroll. These are self-reported notes, not verified credentials.', '', 'Review personal details before putting this file in a public repository. Add links to actual code, calculations, photographs, and test results when available.', ''];for(const e of notes){lines.push(`## ${e.date} — ${e.kind}`,'',e.text,'');}if(!notes.length)lines.push('No field notes have been recorded yet.');download(lines.join('\n'),'text/markdown;charset=utf-8','learning-field-notes.md');toast('Learning log exported. Review it before sharing.');}
document.addEventListener('change',e=>{if(e.target.id==='launch-domain'){launchDomain=e.target.value;$('#launch-books').innerHTML=launchShelf();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-export-learning-log]'))exportLearningLog();});
